def transform(grid):
    runs = []
    for row in grid:
        color = row[0]
        if runs and runs[-1][0] == color:
            runs[-1][1] += 1
        else:
            runs.append([color, 1])

    size = 2 * len(grid) - 2
    out = [[0] * size for _ in range(size)]
    offset = 0
    for color, thickness in runs:
        end = offset + thickness
        for r in range(offset, size - offset):
            for c in range(offset, size - offset):
                if r < end or r >= size - end or c < end or c >= size - end:
                    out[r][c] = color
        offset = end
    return out
